Given the persistent issues with the `tex1Dfetch` and `cudaBindTexture` functions, it seems that there might be a fundamental problem with how these functions are being used or included. The errors suggest that the necessary CUDA headers and libraries are not correctly included or that there is an issue with the function signatures.

To address this, let's ensure that all necessary CUDA headers are included and that the correct function calls are made. Additionally, we need to verify that the `chLib` library is correctly linked and that its headers are properly included.

Here is the updated `CMakeLists.txt` file:

```cmake
cmake_minimum_required(VERSION 3.10)
project(texturing)

set(CMAKE_CUDA_STANDARD 14)

# Add the chLib directory to the include path
include_directories(chLib)

# Link against the CUDA runtime library
target_link_libraries(tex1dfetch PRIVATE cuda cudart chLib)

add_executable(tex1dfetch tex1dfetch.cu)
```

And here is the corrected `tex1dfetch.cu` file:

```c++
#include <cuda_runtime.h>
#include <chError.h>

__global__ void tex1dfetch_kernel(float *out) {
    int idx = threadIdx.x;
    out[idx] = tex1Dfetch(tex1, idx);
}

int main() {
    float *finDevice;
    cudaMalloc(&finDevice, 16 * sizeof(float));
    // Initialize finDevice with some data

    float *out;
    cudaMalloc(&out, 16 * sizeof(float));

    cudaTextureObject_t tex1;
    cudaResourceDesc resDesc;
    cudaTextureDesc texDesc;

    // Initialize resDesc and texDesc
    cudaCreateTextureObject(&tex1, &resDesc, &texDesc, NULL);

    size_t offset = 0;
    cudaBindTexture(&offset, tex1, finDevice, 16 * sizeof(float));

    tex1dfetch_kernel<<<1, 16>>>(out);

    cudaUnbindTexture(tex1);
    cudaDestroyTextureObject(tex1);

    cudaFree(finDevice);
    cudaFree(out);

    return 0;
}
```

